export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string;
  description: string;
  descriptionEn?: string;
  icon: string;
  price?: Price;
  isActive: boolean;
  subServices?: SubService[];
  defaultCommission?: number;
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean;
}

export interface PersonnelDocument {
  id: string;
  title: string;
  file: AttachedFile;
}

export interface Personnel {
  id: string;
  fullName: string;
  roles: string[]; 
  jobDescription?: string; 
  reportsTo?: string;
  email: string;
  username: string;
  password?: string;
  avatar?: string; 
  documents?: PersonnelDocument[]; 
  status: 'active' | 'inactive';
  permissions?: PersonnelPermissions;
  customCommissions?: Record<string, number>;
}

export interface Customer {
  id: string;
  fullName: string;
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string;
  email?: string;
  businessType?: string;
  firstContact: string;
  totalTickets: number;
  source?: string; 
  loyaltyCode?: string;
}

export interface TimelineEntry {
  type: 'status_change' | 'comment' | 'assignment' | 'creation' | 'update' | 'project_update' | 'invoice_created';
  title: string;
  description?: string; 
  actorName: string; 
  timestamp: string;
  visibility?: 'public' | 'internal';
}

export interface Payment {
  id: string;
  amount: number;
  currency: Currency;
  date: string;
  type: 'deposit' | 'settlement' | 'installment';
  note?: string;
}

export interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate?: string;
  customerName: string;
  companyName?: string;
  items: InvoiceItem[];
  currency: Currency;
  subTotal: number;
  taxRate: number;
  taxAmount: number;
  discount: number;
  total: number;
  note?: string;
  issuedBy: string;
}

export interface ProjectMilestone {
  id: string;
  title: string;
  isCompleted: boolean;
  dueDate?: string;
}

export interface ProjectRisk {
  id: string;
  title: string;
  impact: 'Low' | 'Medium' | 'High';
}

export interface ProjectTeamMember {
  userId: string;
  role: string;
  responsibility: string;
  joinedAt: string;
}

export interface ProjectDetails {
  isActive: boolean;
  tariff?: Price;
  startDate: string;
  endDate: string;
  teamMemberIds: string[]; 
  teamMembers?: ProjectTeamMember[];
  projectFiles: AttachedFile[];
  payments: Payment[];
  invoices?: Invoice[];
  milestones?: ProjectMilestone[];
  risks?: ProjectRisk[];
  progress: number; 
  statusNote?: string;
}

export interface Ticket {
  id: string;
  customerName: string; 
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string; 
  businessType?: string; 
  serviceId: string;
  selectedSubServices?: string[];
  description: string;
  files?: AttachedFile[];
  status: TicketStatus;
  createdAt: string;
  aiAnalysis?: string;
  priority?: 'Low' | 'Medium' | 'High';
  assignedTo?: string;
  timeline: TimelineEntry[]; 
  customData?: Record<string, string>; 
  projectData?: ProjectDetails;
  discountApplied?: boolean;
}

export interface InternalMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar?: string;
  recipientIds: string[];
  recipientNames: string[];
  subject: string;
  body: string;
  files?: AttachedFile[];
  createdAt: string;
  readBy: string[];
}

export interface TaskComment {
  id: string;
  authorId: string;
  authorName: string;
  text: string;
  timestamp: string;
}

export interface TaskChecklistItem {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  creatorId: string;
  creatorName: string;
  assigneeIds: string[];
  isCompleted: boolean;
  checklist?: TaskChecklistItem[];
  dueDate?: string;
  priority: 'Low' | 'Medium' | 'High';
  createdAt: string;
  comments: TaskComment[];
}

export interface Meeting {
  id: string;
  title: string;
  date: string;
  startTime: string;
  endTime: string;
  location: string;
  organizerId: string;
  organizerName: string;
  attendeeIds: string[];
  description?: string;
}

export interface KPI {
  id: string;
  title: string;
  titleEn?: string;
  targetValue: number;
  currentValue: number;
  unit: 'percent' | 'count' | 'currency';
  period: 'monthly' | 'quarterly' | 'yearly';
  assignedRole?: string;
  assignedUserId?: string;
  description?: string;
}

export interface CustomForm {
  id: string;
  title: string;
  category: string;
  description?: string;
  fields: FormField[];
  allowedRoles: string[];
  createdAt: string;
  createdBy: string;
}

export interface SalesRecord {
  id: string;
  salespersonId: string;
  salespersonName: string;
  serviceId: string;
  serviceTitle: string;
  customerName: string;
  saleAmount: number;
  currency: Currency;
  commissionRate: number;
  commissionAmount: number;
  depositAccount: string;
  depositDate: string;
  notes?: string;
  createdAt: string;
  updatedAt?: string;
  updatedBy?: string;
}

// --- Reporting Types ---
export type ReportType = 'daily' | 'weekly' | 'monthly';

export interface PerformanceReport {
  id: string;
  userId: string;
  userName: string;
  type: ReportType;
  date: string; // YYYY-MM-DD or YYYY-WW or YYYY-MM
  content: string;
  completedTasks: string[]; // Linear list of task descriptions
  status: 'draft' | 'submitted';
  createdAt: string;
  updatedAt: string;
}

// --- Goal Tracker Types ---
export interface GoalSubTask {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface GoalTask {
  id: string;
  text: string;
  isCompleted: boolean;
  subTasks?: GoalSubTask[]; // New: Sub-steps for break-down
}

export interface GoalCategory {
  id: string;
  title: string;
  color: string; 
  tasks: GoalTask[];
  type: 'personal' | 'business';
}

export type GoalPeriod = 'daily' | 'weekly' | 'monthly' | 'yearly' | 'five_year';

export interface UserGoals {
  id: string; // docId: userId_period
  userId: string;
  userName: string;
  period: GoalPeriod;
  lastUpdated: string;
  categories: GoalCategory[];
}

export interface StrategicObjective {
  id: string;
  title: string;
  description?: string;
  ownerId: string;
  department?: string;
  period: string; // e.g., "Q1 2024"
  status: 'on_track' | 'at_risk' | 'behind' | 'completed';
  keyResults: KeyResult[];
  createdAt: string;
  updatedAt: string;
}

export interface KeyResult {
  id: string;
  title: string;
  targetValue: number;
  currentValue: number;
  unit: string;
  weight: number; 
}

export interface SystemLog {
  id: string;
  actionType: 'CREATE' | 'UPDATE' | 'DELETE' | 'LOGIN' | 'OTHER';
  entity: 'Ticket' | 'Customer' | 'Personnel' | 'Project' | 'Task' | 'Meeting' | 'Message' | 'System' | 'KPI' | 'CustomForm' | 'Sale' | 'Report' | 'Goals' | 'Objective';
  entityId?: string;
  details: string;
  actorName: string;
  actorId?: string;
  timestamp: string;
  backupData?: any;
  collectionName?: string;
}

export interface FeaturedBusiness {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
  websiteUrl?: string;
  contactNumber?: string;
  category: string;
  isGold: boolean;
}

export type ViewState = 'landing' | 'new-ticket' | 'tracking' | 'admin';

export type FormFieldType = 'text' | 'textarea' | 'email' | 'tel' | 'select' | 'header' | 'date' | 'checkbox';

export interface FormField {
  id: string;
  key: string; 
  label: string;
  labelEn?: string;
  type: FormFieldType;
  required: boolean;
  placeholder?: string;
  placeholderEn?: string;
  options?: string[]; 
  isSystem?: boolean; 
  order: number;
}

export interface InvoiceTemplate {
  companyName: string;
  logoUrl?: string;
  address: string;
  phone: string;
  website?: string;
  footerText: string;
  termsConditions: string;
  defaultTaxRate: number;
  colorTheme: string;
}

export type AssignmentMode = 'manual' | 'auto_load_balance' | 'random';

export interface AssignmentConfig {
  mode: AssignmentMode;
  serviceRoleMap: Record<string, string>; 
}

export interface AppConfig {
  appTitle: string;
  appTitleEn: string;
  appSubtitle: string;
  appSubtitleEn: string;
  landingHeroTitle?: string;
  landingHeroSubtitle?: string;
  footerText?: string;
  dailyTips?: string[];
  showDailyTips?: boolean;
  featuredBusinesses?: FeaturedBusiness[];
  formFields: FormField[];
  personnelRoles?: string[]; 
  invoiceTemplate?: InvoiceTemplate;
  assignmentConfig?: AssignmentConfig;
  topPerformerId?: string; // Master choice
}

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals, logSystemAction } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-pink-50 border-pink-200 text-pink-700 header-pink', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'روزانه',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه (Annual)',
            five_year: 'چشم‌انداز ۵ ساله',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هنوز هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف پرسنل:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'Break down (خرد کردن هدف)',
            print: 'خروجی چاپ A4 (پوستر اهداف)',
            reportTitle: 'برنامه راهبردی و اهداف فردی',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year Vision',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Print A4 Poster',
            reportTitle: 'Strategic Plan & Individual Goals',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;

        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] };
            }
            return c;
        });

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newCompleted = !t.isCompleted;
                        const updatedSubTasks = t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted }));
                        return { ...t, isCompleted: newCompleted, subTasks: updatedSubTasks };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newSub: GoalSubTask = { id: `st-${Date.now()}`, text, isCompleted: false };
                        return { ...t, subTasks: [...(t.subTasks || []), newSub], isCompleted: false };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st);
                        const allDone = updatedSubTasks?.every(st => st.isCompleted) || false;
                        return { ...t, subTasks: updatedSubTasks, isCompleted: allDone };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.filter(t => t.id !== taskId) };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) {
            setEditingTitleId(null);
            return;
        }
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, title: newTitle } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        const done = task.subTasks.filter(st => st.isCompleted).length;
        return Math.round((done / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse">در حال بارگذاری اهداف...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    return (
        <div className="space-y-8 animate-fade-in pb-12">
            {/* Header Area (Print Hidden) */}
            <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden print:hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-bl-full -z-10 opacity-50"></div>

                <div className="shrink-0 w-full lg:w-1/3">
                    <h2 className="text-3xl font-black text-gray-900 mb-2 uppercase">{t.title}</h2>
                    <div className="flex items-center gap-2 text-gray-400 mb-6 font-bold text-sm">
                        {periodIcons[activePeriod]}
                        {new Date().toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                    </div>

                    <div className="flex bg-gray-100 p-1 rounded-2xl mb-6 overflow-x-auto no-scrollbar">
                        {(['daily', 'weekly', 'monthly', 'yearly', 'five_year'] as GoalPeriod[]).map(p => (
                            <button 
                                key={p}
                                onClick={() => { setActivePeriod(p); setExpandedTaskId(null); }}
                                className={`flex-1 min-w-[80px] py-2 rounded-xl text-[10px] font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                            >
                                {t[p]}
                            </button>
                        ))}
                    </div>

                    <div className="flex flex-col gap-3">
                        {isMaster && (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">{t.masterView}</label>
                                <select 
                                    className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-100"
                                    value={selectedUserId}
                                    onChange={(e) => { setSelectedUserId(e.target.value); setExpandedTaskId(null); }}
                                >
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            </div>
                        )}
                        <button 
                            onClick={handlePrint}
                            className="w-full py-3 bg-indigo-600 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 border border-indigo-500"
                        >
                            <IconPrinter className="w-4 h-4" /> {t.print}
                        </button>
                    </div>
                </div>

                {/* Progress Circle */}
                <div className="flex flex-col items-center gap-2 lg:border-r lg:px-8 border-gray-100">
                    <div className="relative w-32 h-32 flex items-center justify-center">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="64" cy="64" r="54" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" />
                            <circle cx="64" cy="64" r="54" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={339.292} strokeDashoffset={339.292 - (stats.percent / 100) * 339.292} className={`${activePeriod === 'five_year' ? 'text-purple-600' : 'text-indigo-600'} transition-all duration-1000 ease-out`} />
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-2xl font-black text-gray-900">{stats.percent}%</span>
                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{t.progress}</span>
                        </div>
                    </div>
                </div>

                {/* Categories Overview */}
                <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                    {currentUserGoals?.categories.map(cat => {
                        const catTotal = cat.tasks.length;
                        const catDone = cat.tasks.filter(t => t.isCompleted).length;
                        const catProgress = catTotal > 0 ? Math.round((catDone / catTotal) * 100) : 0;
                        return (
                            <div key={cat.id} className="bg-gray-50 p-3 rounded-2xl flex flex-col justify-center border border-gray-100">
                                <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-1">{cat.title}</div>
                                <div className="flex items-center justify-between gap-2">
                                    <div className="flex-grow bg-gray-200 h-1.5 rounded-full overflow-hidden">
                                        <div className={`h-full rounded-full transition-all duration-1000 ${cat.color.split(' ')[2].replace('text-', 'bg-')}`} style={{ width: `${catProgress}%` }}></div>
                                    </div>
                                    <span className="text-[10px] font-black text-gray-700">{catProgress}%</span>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* --- PRINT ONLY LAYOUT (Highly Aesthetic Poster Style) --- */}
            <div className="hidden print:flex flex-col h-[267mm] w-[180mm] mx-auto bg-white overflow-hidden p-0 relative border-[8px] border-indigo-600">
                {/* Decorative Background */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-bl-full -z-10"></div>
                <div className="absolute bottom-0 left-0 w-32 h-32 bg-indigo-50 rounded-tr-full -z-10"></div>

                {/* Header Poster Banner */}
                <div className="bg-indigo-600 p-8 flex items-center justify-between text-white overflow-hidden relative">
                    <div className="absolute left-0 top-0 w-full h-full opacity-10 flex items-center justify-center pointer-events-none">
                        <IconTarget className="w-64 h-64 scale-150 rotate-12" />
                    </div>
                    <div className="relative z-10 flex items-center gap-6">
                        <div className="w-24 h-24 rounded-3xl border-4 border-white/30 overflow-hidden shadow-2xl bg-white/10 backdrop-blur">
                            {selectedPerson?.avatar ? (
                                <img src={selectedPerson.avatar} className="w-full h-full object-cover" alt="Profile" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-3xl font-black text-white/50">{selectedPerson?.fullName.charAt(0)}</div>
                            )}
                        </div>
                        <div>
                            <h1 className="text-2xl font-black mb-1">{selectedPerson?.fullName}</h1>
                            <div className="flex flex-wrap gap-1.5">
                                {selectedPerson?.roles.map((r, i) => (
                                    <span key={i} className="text-[10px] font-black bg-white/20 px-2 py-0.5 rounded-lg border border-white/30 uppercase tracking-widest">{r}</span>
                                ))}
                            </div>
                        </div>
                    </div>
                    <div className="relative z-10 text-left flex flex-col items-end">
                        <div className="text-4xl font-black opacity-40 uppercase mb-2">TARGETS</div>
                        <div className="bg-white/10 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/20 text-center min-w-[80px]">
                            <div className="text-2xl font-black">{stats.percent}%</div>
                            <div className="text-[8px] font-black uppercase tracking-tighter opacity-70">Strategic Progress</div>
                        </div>
                    </div>
                </div>

                {/* Period & Title Section */}
                <div className="p-8 pb-4 flex justify-between items-end border-b border-gray-100">
                    <div>
                        <h2 className="text-xl font-black text-indigo-900 mb-1">{t.reportTitle}</h2>
                        <div className="flex items-center gap-2 text-indigo-400 font-bold text-xs uppercase tracking-widest">
                            {periodIcons[activePeriod]} {t[activePeriod]} ( {new Date().getFullYear()} )
                        </div>
                    </div>
                    <div className="text-left">
                        <div className="text-[9px] font-black text-gray-400 mb-1">DATE ISSUED</div>
                        <div className="text-sm font-bold text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</div>
                    </div>
                </div>

                {/* Goals Grid Layout (Compact for Print) */}
                <div className="flex-grow p-8 grid grid-cols-2 gap-6 overflow-hidden">
                    {currentUserGoals?.categories.map((cat) => {
                        const catDone = cat.tasks.filter(t => t.isCompleted).length;
                        const catProgress = cat.tasks.length > 0 ? Math.round((catDone / cat.tasks.length) * 100) : 0;
                        const headerColors: any = {
                            'header-blue': 'border-blue-600 text-blue-600 bg-blue-50/50',
                            'header-pink': 'border-pink-600 text-pink-600 bg-pink-50/50',
                            'header-green': 'border-emerald-600 text-emerald-600 bg-emerald-50/50',
                            'header-orange': 'border-orange-600 text-orange-600 bg-orange-50/50',
                            'header-purple': 'border-purple-600 text-purple-600 bg-purple-50/50'
                        };
                        const hColor = headerColors[cat.color.split(' ').find(c => c.startsWith('header-')) || ''] || 'border-indigo-600 text-indigo-600 bg-indigo-50/50';

                        return (
                            <div key={cat.id} className="flex flex-col border border-gray-200 rounded-3xl overflow-hidden bg-white shadow-sm break-inside-avoid h-fit max-h-[100%]">
                                <div className={`px-4 py-2 border-b-2 font-black text-[10px] uppercase tracking-wider flex justify-between items-center ${hColor}`}>
                                    <span className="flex items-center gap-2">
                                        {cat.type === 'business' ? <IconBriefcase className="w-3 h-3" /> : <IconUsers className="w-3 h-3" />}
                                        {cat.title}
                                    </span>
                                    <span>{catProgress}%</span>
                                </div>
                                <div className="p-4 space-y-3 overflow-hidden">
                                    {cat.tasks.map((task, tidx) => (
                                        <div key={task.id} className="space-y-1">
                                            <div className="flex items-start gap-3">
                                                <div className={`w-3.5 h-3.5 rounded mt-0.5 border flex items-center justify-center shrink-0 ${task.isCompleted ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-gray-300'}`}>
                                                    {task.isCompleted && <IconCheck className="w-2.5 h-2.5 text-white" />}
                                                </div>
                                                <div className="flex-grow">
                                                    <div className={`text-[11px] font-black leading-tight ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>
                                                        {task.text}
                                                    </div>
                                                    {/* Subtasks in print */}
                                                    <div className="mt-1.5 space-y-1 pl-4 border-r border-indigo-100">
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-2 text-[9px] text-gray-500 font-bold">
                                                                <span className={`w-2 h-2 rounded-full shrink-0 ${st.isCompleted ? 'bg-indigo-400' : 'bg-gray-200'}`}></span>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-[9px] text-gray-300 italic py-4 text-center">No goals set for this category</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer Poster */}
                <div className="p-8 border-t border-gray-100 flex justify-between items-center bg-gray-50/50">
                    <div className="max-w-[70%]">
                        <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1">MOTIVATION</p>
                        <p className="text-xs font-bold text-gray-600 italic">"{t.visionNote}"</p>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center mb-1 shadow-lg shadow-indigo-100">
                            <IconShield className="w-5 h-5 text-white" />
                        </div>
                        <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">COMPANY CRM SYSTEM</span>
                    </div>
                </div>
            </div>

            {/* --- WEB ONLY LIST (Original Main Grid) --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6 print:hidden">
                {currentUserGoals?.categories.map((cat) => {
                    const catTotal = cat.tasks.length;
                    const catDone = cat.tasks.filter(t => t.isCompleted).length;
                    const catProgress = catTotal > 0 ? Math.round((catDone / catTotal) * 100) : 0;

                    const headerColors: any = {
                        'header-blue': 'bg-blue-400',
                        'header-pink': 'bg-pink-400',
                        'header-green': 'bg-emerald-400',
                        'header-orange': 'bg-orange-400',
                        'header-purple': 'bg-purple-400'
                    };
                    const hColor = headerColors[cat.color.split(' ').find(c => c.startsWith('header-')) || ''] || 'bg-indigo-400';

                    return (
                        <div key={cat.id} className={`bg-white rounded-3xl border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[500px] group/col ${activePeriod === 'five_year' ? 'ring-1 ring-purple-50' : ''}`}>
                            {/* Column Header */}
                            <div className={`${hColor} p-4 text-center text-white font-black text-xs uppercase tracking-wider relative`}>
                                {editingTitleId === cat.id ? (
                                    <input 
                                        autoFocus
                                        className="w-full bg-white/20 text-white placeholder-white/50 px-2 py-1 rounded outline-none border border-white/30 text-center"
                                        defaultValue={cat.title}
                                        onBlur={(e) => handleUpdateCategoryTitle(cat.id, e.target.value)}
                                        onKeyDown={(e) => e.key === 'Enter' && handleUpdateCategoryTitle(cat.id, (e.target as HTMLInputElement).value)}
                                    />
                                ) : (
                                    <div className="flex items-center justify-center gap-2">
                                        {cat.type === 'business' ? <IconBriefcase className="w-3 h-3" /> : <IconUsers className="w-3 h-3" />}
                                        <span onClick={() => canEdit && setEditingTitleId(cat.id)} className={canEdit ? "cursor-pointer hover:underline" : ""}>
                                            {cat.title}
                                        </span>
                                        {canEdit && (
                                            <button onClick={() => setEditingTitleId(cat.id)} className="flex items-center justify-center opacity-40 hover:opacity-100 cursor-pointer">
                                                <IconEdit className="w-3 h-3" />
                                            </button>
                                        )}
                                    </div>
                                )}
                            </div>

                            {/* Summary Box */}
                            <div className="bg-gray-50 border-b border-gray-100 p-4 grid grid-cols-3 gap-2 text-center">
                                <div><div className="text-[9px] font-black text-gray-400 uppercase mb-1">{t.done}</div><div className="text-base font-black text-gray-900">{catDone}</div></div>
                                <div><div className="text-[9px] font-black text-gray-400 uppercase mb-1">{t.total}</div><div className="text-base font-black text-gray-900">{catTotal}</div></div>
                                <div><div className="text-[9px] font-black text-gray-400 uppercase mb-1">{t.progress}</div><div className={`text-base font-black ${activePeriod === 'five_year' ? 'text-purple-600' : 'text-indigo-600'}`}>{catProgress}%</div></div>
                            </div>

                            {/* Task List */}
                            <div className="flex-grow overflow-y-auto p-4 space-y-4 custom-scrollbar">
                                {cat.tasks.map((task) => {
                                    const taskProg = calculateTaskProgress(task);
                                    const isExpanded = expandedTaskId === task.id;
                                    const hasSteps = (task.subTasks || []).length > 0;

                                    return (
                                        <div key={task.id} className={`flex flex-col rounded-2xl border transition-all ${isExpanded ? 'ring-2 ring-indigo-200 border-indigo-200' : 'border-gray-100 shadow-sm'} ${task.isCompleted ? 'bg-gray-50' : 'bg-white'}`}>
                                            <div className="flex items-start gap-3 p-3">
                                                <button 
                                                    onClick={() => toggleTask(cat.id, task.id)}
                                                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all ${task.isCompleted ? 'bg-indigo-600 border-indigo-600 text-white shadow-sm' : 'border-gray-200 bg-white hover:border-indigo-400'}`}
                                                >
                                                    {task.isCompleted && <IconCheck className="w-3 h-3" />}
                                                </button>

                                                <div className="flex-grow flex flex-col min-w-0" onClick={() => setExpandedTaskId(isExpanded ? null : task.id)}>
                                                    <span className={`text-[12px] font-black leading-tight cursor-pointer ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-700'}`}>
                                                        {task.text}
                                                    </span>

                                                    {/* Goal Progress Bar */}
                                                    {(hasSteps || isExpanded) && (
                                                        <div className="mt-2 w-full">
                                                            <div className="flex justify-between items-center mb-1">
                                                                <span className="text-[9px] font-black text-indigo-400 uppercase">{t.progress}</span>
                                                                <span className="text-[9px] font-black text-indigo-600">{taskProg}%</span>
                                                            </div>
                                                            <div className="w-full bg-gray-100 h-1 rounded-full overflow-hidden">
                                                                <div className={`h-full transition-all duration-700 ${taskProg === 100 ? 'bg-green-500' : 'bg-indigo-600'}`} style={{ width: `${taskProg}%` }}></div>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col gap-1 shrink-0 opacity-0 group-hover/col:opacity-100 transition-opacity">
                                                     <button onClick={() => setExpandedTaskId(isExpanded ? null : task.id)} className={`p-1.5 rounded-lg hover:bg-gray-100 text-gray-400 ${isExpanded ? 'text-indigo-600' : ''}`} title={t.breakDown}>
                                                         <IconActivity className="w-3 h-3" />
                                                     </button>
                                                     <button onClick={() => removeTask(cat.id, task.id)} className="p-1.5 rounded-lg hover:bg-red-50 text-red-200 hover:text-red-500">
                                                         <IconTrash className="w-3 h-3" />
                                                     </button>
                                                </div>
                                            </div>

                                            {/* Sub-tasks / Break-down View */}
                                            {isExpanded && (
                                                <div className="px-3 pb-4 space-y-2 animate-slide-in">
                                                    <div className="h-px bg-gray-100 mx-2 mb-3"></div>
                                                    <div className="space-y-2 pl-4 border-r-2 border-indigo-50">
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-3 group/step">
                                                                <button 
                                                                    onClick={() => toggleSubTask(cat.id, task.id, st.id)}
                                                                    className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${st.isCompleted ? 'bg-indigo-400 border-indigo-400 text-white' : 'border-gray-300 bg-white hover:border-indigo-200'}`}
                                                                >
                                                                    {st.isCompleted && <IconCheck className="w-2.5 h-2.5" />}
                                                                </button>
                                                                <span className={`text-[11px] font-bold flex-grow ${st.isCompleted ? 'text-gray-300 line-through' : 'text-gray-500'}`}>
                                                                    {st.text}
                                                                </span>
                                                                <button onClick={() => {
                                                                    const updated = task.subTasks?.filter(s => s.id !== st.id);
                                                                    const allDone = updated?.every(s => s.isCompleted) || false;
                                                                    const updatedCategories = currentUserGoals.categories.map(c => 
                                                                        c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: updated, isCompleted: allDone } : t) } : c
                                                                    );
                                                                    const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
                                                                    setCurrentUserGoals(updatedGoals);
                                                                    saveUserGoals(updatedGoals);
                                                                }} className="text-red-200 hover:text-red-400 opacity-0 group-hover/step:opacity-100 transition-opacity">✕</button>
                                                            </div>
                                                        ))}
                                                        <input 
                                                            className="w-full bg-gray-50 border-none rounded-lg px-3 py-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-100"
                                                            placeholder={t.addSubTask}
                                                            onKeyDown={(e) => {
                                                                if (e.key === 'Enter') {
                                                                    handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value);
                                                                    (e.target as HTMLInputElement).value = '';
                                                                }
                                                            }}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {cat.tasks.length === 0 && (
                                    <div className="h-full flex flex-col items-center justify-center text-center py-10 opacity-40">
                                        <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center mb-2 border border-dashed border-gray-200">
                                            <IconTarget className="w-6 h-6 text-gray-200" />
                                        </div>
                                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.empty}</span>
                                    </div>
                                )}
                            </div>

                            {/* Column Footer */}
                            {canEdit && (
                                <div className="p-4 border-t border-gray-50">
                                    <button 
                                        onClick={() => handleAddTask(cat.id)}
                                        className="w-full py-2.5 rounded-2xl border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] uppercase tracking-widest hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50 transition-all flex items-center justify-center gap-2"
                                    >
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            <div className="text-center pt-8 border-t border-gray-100 print:hidden">
                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.smartNote}</p>
                <p className="text-[10px] font-bold text-gray-400 mt-2">{t.lastUpdate} {new Date(currentUserGoals?.lastUpdated || '').toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</p>
            </div>

            <style>{`
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
                @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .animate-fade-in { animation: fade-in 0.4s ease-out forwards; }
                @keyframes slide-in { from { opacity: 0; transform: translateX(5px); } to { opacity: 1; transform: translateX(0); } }
                .animate-slide-in { animation: slide-in 0.2s ease-out forwards; }

                @media print {
                    @page { size: A4; margin: 0; }
                    body { background: white !important; margin: 0; padding: 0; }
                    #root > div > header, #root > div > footer, #root > div > nav, #root > div > .fixed, .print\\:hidden { display: none !important; }
                    main { padding: 0 !important; max-width: 100% !important; margin: 0 !important; }
                    .print\\:flex { display: flex !important; }
                    .print\\:block { display: block !important; }
                    .print\\:grid { display: grid !important; }

                    /* Ensure colors are printed */
                    * { -webkit-print-color-adjust: exact !important; color-adjust: exact !important; }

                    /* Force content to stay within A4 */
                    .print-container { height: 297mm; width: 210mm; }
                }
            `}</style>
        </div>
    );
};

export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string;
  description: string;
  descriptionEn?: string;
  icon: string;
  price?: Price;
  isActive: boolean;
  subServices?: SubService[];
  defaultCommission?: number;
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean;
}

export interface PersonnelDocument {
  id: string;
  title: string;
  file: AttachedFile;
}

export interface Personnel {
  id: string;
  fullName: string;
  roles: string[]; 
  jobDescription?: string; 
  reportsTo?: string;
  email: string;
  username: string;
  password?: string;
  avatar?: string; 
  documents?: PersonnelDocument[]; 
  status: 'active' | 'inactive';
  permissions?: PersonnelPermissions;
  customCommissions?: Record<string, number>;
}

export interface Customer {
  id: string;
  fullName: string;
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string;
  email?: string;
  businessType?: string;
  firstContact: string;
  totalTickets: number;
  source?: string; 
  loyaltyCode?: string;
}

export interface TimelineEntry {
  type: 'status_change' | 'comment' | 'assignment' | 'creation' | 'update' | 'project_update' | 'invoice_created';
  title: string;
  description?: string; 
  actorName: string; 
  timestamp: string;
  visibility?: 'public' | 'internal';
}

export interface Payment {
  id: string;
  amount: number;
  currency: Currency;
  date: string;
  type: 'deposit' | 'settlement' | 'installment';
  note?: string;
}

export interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate?: string;
  customerName: string;
  companyName?: string;
  items: InvoiceItem[];
  currency: Currency;
  subTotal: number;
  taxRate: number;
  taxAmount: number;
  discount: number;
  total: number;
  note?: string;
  issuedBy: string;
}

export interface ProjectMilestone {
  id: string;
  title: string;
  isCompleted: boolean;
  dueDate?: string;
}

export interface ProjectRisk {
  id: string;
  title: string;
  impact: 'Low' | 'Medium' | 'High';
}

export interface ProjectTeamMember {
  userId: string;
  role: string;
  responsibility: string;
  joinedAt: string;
}

export interface ProjectDetails {
  isActive: boolean;
  tariff?: Price;
  startDate: string;
  endDate: string;
  teamMemberIds: string[]; 
  teamMembers?: ProjectTeamMember[];
  projectFiles: AttachedFile[];
  payments: Payment[];
  invoices?: Invoice[];
  milestones?: ProjectMilestone[];
  risks?: ProjectRisk[];
  progress: number; 
  statusNote?: string;
}

export interface Ticket {
  id: string;
  customerName: string; 
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string; 
  businessType?: string; 
  serviceId: string;
  selectedSubServices?: string[];
  description: string;
  files?: AttachedFile[];
  status: TicketStatus;
  createdAt: string;
  aiAnalysis?: string;
  priority?: 'Low' | 'Medium' | 'High';
  assignedTo?: string;
  timeline: TimelineEntry[]; 
  customData?: Record<string, string>; 
  projectData?: ProjectDetails;
  discountApplied?: boolean;
}

export interface InternalMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar?: string;
  recipientIds: string[];
  recipientNames: string[];
  subject: string;
  body: string;
  files?: AttachedFile[];
  createdAt: string;
